import string, random
from pwn import remote
import time

HOST, PORT = 'crypto.chal.csaw.io', 8040
N_set = [20, 30, 40, 50, 60, 80, 100, 120, 140]

def rand_ascii(n):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=n))

def get_length(inp):
    r = remote(HOST, PORT, timeout=8)
    banner = r.recvuntil(b'input:')
    r.sendline(inp.encode())
    reply = r.recvuntil(b'\n')
    try:
        response_line = reply.decode('utf-8')
    except Exception:
        response_line = str(reply)
    length = None
    for line in response_line.splitlines():
        if 'len:' in line.lower():
            try:
                length = int(line.split('len:')[-1].split(')')[0].strip())
            except:
                pass
    r.close()
    return length, response_line

results = []
for N in N_set:
    data = rand_ascii(N)
    length, line = get_length(data)
    results.append((N, length, data, line))
    time.sleep(0.5)

with open('/home/ctfplayer/ctf_files/ascii_length_results.txt', 'w') as f:
    for N, length, data, line in results:
        f.write(f"Input length: {N}, ciphertext length: {length}\n")
        f.write(f"Input: {data}\nOutput: {line}\n\n")
print('Lengths written to ascii_length_results.txt')

from pwn import remote
import string, random, sys, time

def rand_ascii(n):
    chars = string.ascii_letters + string.digits + string.punctuation
    return ''.join(random.choice(chars) for _ in range(n))

HOST = 'crypto.chal.csaw.io'
PORT = 8040

for l in [40, 60, 80, 100, 120, 140]:
    for trial in range(2):
        payload = rand_ascii(l)
        print(f'Connecting for input length {l} (trial {trial+1})...')
        r = remote(HOST, PORT)
        r.sendlineafter(b'input:', payload.encode())
        out = b''
        t0 = time.time()
        while True:
            try:
                d = r.recv(timeout=0.7)
                if not d:
                    break
                out += d
            except Exception:
                break
            if time.time()-t0 > 5.0:
                break
        r.close()
        print(f'Input length: {l}, output/ciphertext length: {len(out)}, ord(last byte): {ord(chr(out[-1])) if out else None}')
